use crate::aap::caps::state_read;

struct Node;

/// Keys the subscription store may hold its list under, tried in order.
const KEYS: &[&str] = &["urls", "subscriptions", "feeds", "subscription-list"];

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        let mut urls: Vec<String> = Vec::new();
        for key in KEYS {
            if let Some(value) = state_read::get(key) {
                let parsed = parse_list(&value);
                if !parsed.is_empty() {
                    urls = parsed;
                    break;
                }
            }
        }
        SubscriptionList { urls: dedupe(urls) }
    }
}

/// Parse a stored list: a JSON array of strings, a JSON object whose first
/// array holds strings, or plain text with one URL per line or comma.
fn parse_list(raw: &str) -> Vec<String> {
    let trimmed = raw.trim();
    if trimmed.starts_with('[') || trimmed.starts_with('{') {
        if let Some(list) = parse_json_string_array(trimmed) {
            return list
                .into_iter()
                .map(|s| s.trim().to_string())
                .filter(|s| !s.is_empty())
                .collect();
        }
    }
    trimmed
        .split(|c| c == '\n' || c == '\r' || c == ',')
        .map(|s| s.trim())
        .filter(|s| !s.is_empty() && !s.starts_with('#'))
        .map(|s| s.trim_matches('"').trim().to_string())
        .filter(|s| !s.is_empty())
        .collect()
}

fn dedupe(urls: Vec<String>) -> Vec<String> {
    let mut out: Vec<String> = Vec::with_capacity(urls.len());
    for u in urls {
        if !out.iter().any(|e| e == &u) {
            out.push(u);
        }
    }
    out
}

/// Find the first `[` and parse the array of string literals that follows.
/// Non-string elements are skipped. Returns None on malformed input.
fn parse_json_string_array(s: &str) -> Option<Vec<String>> {
    let chars: Vec<char> = s.chars().collect();
    let mut i = 0;
    // Skip to the first '[' that is not inside a string.
    let mut in_str = false;
    let mut escaped = false;
    while i < chars.len() {
        let c = chars[i];
        if in_str {
            if escaped {
                escaped = false;
            } else if c == '\\' {
                escaped = true;
            } else if c == '"' {
                in_str = false;
            }
        } else if c == '"' {
            in_str = true;
        } else if c == '[' {
            break;
        }
        i += 1;
    }
    if i >= chars.len() {
        return None;
    }
    i += 1; // past '['
    let mut out = Vec::new();
    let mut depth: i32 = 0;
    while i < chars.len() {
        let c = chars[i];
        match c {
            '"' => {
                let (string, next) = parse_json_string(&chars, i + 1)?;
                if depth == 0 {
                    out.push(string);
                }
                i = next;
                continue;
            }
            '[' | '{' => depth += 1,
            ']' | '}' => {
                if depth == 0 {
                    return Some(out);
                }
                depth -= 1;
            }
            _ => {}
        }
        i += 1;
    }
    None
}

/// Parse a JSON string body starting just after the opening quote.
/// Returns the decoded string and the index just past the closing quote.
fn parse_json_string(chars: &[char], mut i: usize) -> Option<(String, usize)> {
    let mut out = String::new();
    while i < chars.len() {
        let c = chars[i];
        match c {
            '"' => return Some((out, i + 1)),
            '\\' => {
                i += 1;
                let e = *chars.get(i)?;
                match e {
                    '"' => out.push('"'),
                    '\\' => out.push('\\'),
                    '/' => out.push('/'),
                    'b' => out.push('\u{0008}'),
                    'f' => out.push('\u{000C}'),
                    'n' => out.push('\n'),
                    'r' => out.push('\r'),
                    't' => out.push('\t'),
                    'u' => {
                        let hi = read_hex4(chars, i + 1)?;
                        i += 4;
                        if (0xD800..0xDC00).contains(&hi) {
                            if chars.get(i + 1) == Some(&'\\') && chars.get(i + 2) == Some(&'u') {
                                if let Some(lo) = read_hex4(chars, i + 3) {
                                    if (0xDC00..0xE000).contains(&lo) {
                                        let cp = 0x10000 + ((hi - 0xD800) << 10) + (lo - 0xDC00);
                                        out.push(char::from_u32(cp).unwrap_or('\u{FFFD}'));
                                        i += 6;
                                    } else {
                                        out.push('\u{FFFD}');
                                    }
                                } else {
                                    out.push('\u{FFFD}');
                                }
                            } else {
                                out.push('\u{FFFD}');
                            }
                        } else {
                            out.push(char::from_u32(hi).unwrap_or('\u{FFFD}'));
                        }
                    }
                    other => out.push(other),
                }
                i += 1;
            }
            _ => {
                out.push(c);
                i += 1;
            }
        }
    }
    None
}

fn read_hex4(chars: &[char], start: usize) -> Option<u32> {
    let mut v: u32 = 0;
    for k in 0..4 {
        let d = chars.get(start + k)?.to_digit(16)?;
        v = v * 16 + d;
    }
    Some(v)
}

export!(Node);
